local HammerMaker = {}
local PRODUCTS = {
    iron_hammer = { name = "Železno kladivo", ironCost = 4, woodCost = 2, leatherCost = 1, time = 5, cost = 185, prestige = 4, happiness = 2, description = "Železno kladivo za kovaštvo." },
    bronze_hammer = { name = "Bronasto kladivo", bronzeCost = 4, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 450, prestige = 6, happiness = 3, description = "Bronasto kladivo za natančno kovaštvo." },
    silver_hammer = { name = "Srebrno kladivo", silverCost = 4, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 1080, prestige = 11, happiness = 4, description = "Srebrno kladivo za plemiške kovače." },
    gilded_hammer = { name = "Pozlačeno kladivo", goldCost = 1, silverCost = 4, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 2330, prestige = 20, happiness = 5, description = "Pozlačeno kladivo za dvorne kovače." },
    jewel_set_hammer = { name = "Draguljasto kladivo", goldCost = 2, silverCost = 4, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 5000, prestige = 36, happiness = 7, description = "Draguljasto kladivo za kraljevske kovače." },
    royal_sovereign_hammer = { name = "Kraljevski suvereno kladivo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 10700, prestige = 69, happiness = 13, description = "Suvereno kladivo z biseri za krono." },
}
local BUILDINGS = {
    hammer_workshop = { name = "Kladivna delavnica", cost = { gold = 370, wood = 180, stone = 145, iron = 10 }, upkeep = 7, qualityBonus = 5 },
    hammer_house = { name = "Kladivna hiša", cost = { gold = 1285, wood = 365, stone = 285, silver = 8, iron = 8 }, upkeep = 27, qualityBonus = 18 },
    master_hammer_atelier = { name = "Mojstrski kladivni atelje", cost = { gold = 3200, wood = 425, stone = 540, silver = 39, gold = 8 }, upkeep = 75, qualityBonus = 30 },
    sovereign_hammer_palace = { name = "Suverena kladivna palača", cost = { gold = 13600, wood = 650, stone = 860, gold = 88, jewel = 20 }, upkeep = 263, qualityBonus = 55, prestigeBonus = 50 },
}
HammerMaker.ironStock = 16; HammerMaker.bronzeStock = 14; HammerMaker.woodStock = 12; HammerMaker.leatherStock = 10; HammerMaker.silverStock = 8; HammerMaker.goldStock = 6; HammerMaker.jewelStock = 4; HammerMaker.pearlStock = 4
HammerMaker.productStock = {}; HammerMaker.buildings = {}; HammerMaker.maker = nil; HammerMaker.activeMaking = {}; HammerMaker.totalProducts = 0; HammerMaker.dayTimer = 0
function HammerMaker.init() HammerMaker.ironStock=16; HammerMaker.bronzeStock=14; HammerMaker.woodStock=12; HammerMaker.leatherStock=10; HammerMaker.silverStock=8; HammerMaker.goldStock=6; HammerMaker.jewelStock=4; HammerMaker.pearlStock=4; HammerMaker.productStock={}; HammerMaker.buildings={}; HammerMaker.maker=nil; HammerMaker.activeMaking={}; HammerMaker.totalProducts=0; HammerMaker.dayTimer=0; print("[HammerMaker] Royal Hammer Maker System initialized (6 products, 4 buildings)") end
function HammerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HammerMaker.maker={name=n or ("Kladivar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kladivar najet: %s (spretnost: %d)",HammerMaker.maker.name,s),"success") end; return true end
function HammerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HammerMaker.build(id) local ok,e=HammerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HammerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HammerMaker.getQualityBonus() local b=0; for _,bd in ipairs(HammerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HammerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HammerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and HammerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and HammerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and HammerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and HammerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HammerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HammerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HammerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HammerMaker.buildings==0 then return false,"Potrebna kladivna delavnica" end; if not HammerMaker.maker then return false,"Potreben kladivar" end; return true end
function HammerMaker.make(pt,qty) qty=qty or 1; local ok,e=HammerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HammerMaker.ironStock=HammerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then HammerMaker.bronzeStock=HammerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then HammerMaker.woodStock=HammerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then HammerMaker.leatherStock=HammerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then HammerMaker.silverStock=HammerMaker.silverStock-d.silverCost*qty end; if d.goldCost then HammerMaker.goldStock=HammerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HammerMaker.jewelStock=HammerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HammerMaker.pearlStock=HammerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HammerMaker.maker then t=math.max(1,t-math.floor(HammerMaker.maker.skill/13)) end; table.insert(HammerMaker.activeMaking,{id="hammer_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HammerMaker.completeMaking(m) local q=1.0+(HammerMaker.getQualityBonus()/100); if HammerMaker.maker then q=q+(HammerMaker.maker.skill/140) end; q=math.min(2.5,q); HammerMaker.productStock[m.productType]=(HammerMaker.productStock[m.productType] or 0)+m.quantity; HammerMaker.totalProducts=HammerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HammerMaker.maker then HammerMaker.maker.itemsMade=HammerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HammerMaker.maker.skill=math.min(100,HammerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kladivo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"hammer.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function HammerMaker.update(dt) if not _G.state then return end; HammerMaker.dayTimer=HammerMaker.dayTimer+dt; if HammerMaker.dayTimer>=30 then HammerMaker.dayTimer=0; for i=#HammerMaker.activeMaking,1,-1 do local m=HammerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HammerMaker.completeMaking(m); table.remove(HammerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HammerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HammerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HammerMaker.getStats() return {ironStock=HammerMaker.ironStock,bronzeStock=HammerMaker.bronzeStock,woodStock=HammerMaker.woodStock,leatherStock=HammerMaker.leatherStock,silverStock=HammerMaker.silverStock,goldStock=HammerMaker.goldStock,jewelStock=HammerMaker.jewelStock,pearlStock=HammerMaker.pearlStock,productStock=HammerMaker.productStock,numBuildings=#HammerMaker.buildings,hasMaker=HammerMaker.maker~=nil,makerName=HammerMaker.maker and HammerMaker.maker.name or "—",makerSkill=HammerMaker.maker and HammerMaker.maker.skill or 0,activeMaking=#HammerMaker.activeMaking,totalProducts=HammerMaker.totalProducts} end
return HammerMaker
